package com.bananalab.lite;
import java.util.*;import java.util.regex.*;import java.lang.reflect.*;import org.json.*;
/** Complete recipe-selection module; arbitrary Java and arbitrary regex are not accepted. */
final class PlannerContract{
 static JSONObject read(String body)throws Exception{Matcher m=Pattern.compile("^return\\s+("+JavaTextPlan.LIT+")\\s*;$").matcher(body);if(!m.matches())throw new IllegalArgumentException("PlannerProfile.rules debe devolver JSON literal.");JSONObject data=new JSONObject(JavaTextPlan.decode(m.group(1)));validate(data);return data;}
 static void validate(JSONObject data)throws Exception{RuntimeProgram.keys(data,"version","rules");if(data.getInt("version")!=1)throw new IllegalArgumentException("Versión del planificador desconocida.");JSONArray rules=data.getJSONArray("rules");if(rules.length()<1||rules.length()>8)throw new IllegalArgumentException("De1 a8 reglas del planificador.");Set<String> ids=new HashSet<>(),phrases=new HashSet<>();for(int i=0;i<rules.length();i++){JSONObject rule=rules.getJSONObject(i);RuntimeProgram.keys(rule,"id","phrase","steps");String id=rule.getString("id"),phrase=rule.getString("phrase");if(!id.matches("[a-z][a-z0-9_]{0,23}")||!ids.add(id)||!phrases.add(phrase)||phrase.length()>120||!phrase.replace("{actor}","actor").replace("{otro}","otro").equals(ChatLanguage.normalize(phrase.replace("{actor}","actor").replace("{otro}","otro")))||!phrase.matches("[a-z0-9 {}]+")||count(phrase,"{actor}")!=1||count(phrase,"{otro}")>1||phrase.replace("{actor}","").replace("{otro}","").contains("{")||phrase.matches("(?s).*\\b(?:java|aplica|deshace|borra|descarta|reconstruye|actualiza|firma|importa|exporta)\\b.*"))throw new IllegalArgumentException("Plantilla inválida o control reservado.");String literal=phrase.replace("{actor}","").replace("{otro}","").trim();if(literal.length()<6)throw new IllegalArgumentException("La plantilla necesita al menos seis letras de contexto.");JSONArray steps=rule.getJSONArray("steps");if(steps.length()<1||steps.length()>8)throw new IllegalArgumentException("De1 a8 pasos por receta.");for(int n=0;n<steps.length();n++){JSONObject step=steps.getJSONObject(n);RuntimeProgram.keys(step,"who","move");if(!step.getString("who").matches("actor|otro|ambos")||(!phrase.contains("{otro}")&&!step.getString("who").equals("actor")))throw new IllegalArgumentException("Destinatario ausente en la plantilla.");JavaPatchPolicy.sequence(step.getString("move"));if(step.getString("move").contains(","))throw new IllegalArgumentException("Un movimiento por paso.");}}}
 static String quote(String text){if(text.length()>12000)throw new IllegalArgumentException("Receta demasiado larga.");return "\""+text.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r")+"\"";}
 static int count(String s,String needle){return (s.length()-s.replace(needle,"").length())/needle.length();}
 static String pattern(String phrase){StringBuilder out=new StringBuilder("^");Matcher m=Pattern.compile("\\{(actor|otro)\\}").matcher(phrase);int at=0;while(m.find()){out.append(Pattern.quote(phrase.substring(at,m.start()))).append("([a-z][a-z0-9_ ]{0,39}?)");at=m.end();}return out.append(Pattern.quote(phrase.substring(at))).append('$').toString();}
 static String[] expected(JSONObject data,String input,float[] scores)throws Exception{JSONArray rules=data.getJSONArray("rules");float best=0;String[] result=null;for(int i=0;i<rules.length();i++){JSONObject r=rules.getJSONObject(i);Matcher match=Pattern.compile(pattern(r.getString("phrase"))).matcher(input);float score=1f+r.getString("phrase").replace("{actor}","").replace("{otro}","").length()*.001f+(i<scores.length?scores[i]:0);if(match.matches()&&score>best){best=score;boolean otherFirst=r.getString("phrase").indexOf("{otro}")>=0&&r.getString("phrase").indexOf("{otro}")<r.getString("phrase").indexOf("{actor}");result=new String[]{r.getString("id"),match.group(otherFirst?2:1),r.getString("phrase").contains("{otro}")?match.group(otherFirst?1:2):"",r.getJSONArray("steps").toString()};}}return result;}
 static String source(JSONObject data)throws Exception{validate(data);StringBuilder java=new StringBuilder("package com.bananalab.patch; public final class BananaProjectPatch { public static String[] plan(String input,float[] scores){float best=0;String[] result=null;");JSONArray rules=data.getJSONArray("rules");for(int i=0;i<rules.length();i++){JSONObject r=rules.getJSONObject(i);String phrase=r.getString("phrase");boolean otherFirst=phrase.contains("{otro}")&&phrase.indexOf("{otro}")<phrase.indexOf("{actor}");java.append("{java.util.regex.Matcher m=java.util.regex.Pattern.compile(").append(quote(pattern(phrase))).append(").matcher(input);float score=").append(Float.toString(1f+phrase.replace("{actor}","").replace("{otro}","").length()*.001f)).append("f+(scores.length>").append(i).append("?scores[").append(i).append("]:0f);if(m.matches()&&score>best){best=score;result=new String[]{").append(quote(r.getString("id"))).append(",m.group(").append(otherFirst?2:1).append("),").append(phrase.contains("{otro}")?"m.group("+(otherFirst?1:2)+")":"\"\"").append(',').append(quote(r.getJSONArray("steps").toString())).append("};}}");}return java.append("return result;} }").toString();}
 static int check(Method method,JSONObject data)throws Exception{List<String> tests=new ArrayList<>(Arrays.asList("hola","aplica sustitucion java","deshace sustitucion java","borra todo","crea una banana","publica el borrador","fito besa a bani"));JSONArray rules=data.getJSONArray("rules");for(int i=0;i<rules.length();i++){String phrase=rules.getJSONObject(i).getString("phrase");tests.add(phrase.replace("{actor}","fito").replace("{otro}","bani"));tests.add(phrase.replace("{actor}","el zorro").replace("{otro}","la banana"));}for(String input:tests)for(int variant=0;variant<2;variant++){float[] scores=new float[rules.length()];if(variant==1)Arrays.fill(scores,-3f);String[] got=(String[])method.invoke(null,input,scores),wanted=expected(data,input,scores);if(!Arrays.equals(got,wanted))throw new IllegalArgumentException("El módulo no coincide con su contrato: "+input);}return tests.size()*2;}
 static int samples(JSONObject data)throws Exception{return (7+data.getJSONArray("rules").length()*2)*2;}
}
